node - <<'NODE'
const https = require('https');
const url='https://ourworldindata.org/grapher/deaths-in-wars-by-war-1800-2011-bar-chart.csv?v=1&csvType=full&useColumnShortNames=false';
https.get(url,res=>{let data='';res.on('data',c=>data+=c);res.on('end',()=>{
  const interstate = new Set([
    'World War II','World War I','Second Sino-Japanese War','Vietnam War','Napoleonic Wars','Korean War','Iran-Iraq War','Crimean War','Franco-Prussian War','Second Balkan War','Russo-Japanese War','Greco-Turkish War','Durrani Empire-Sikh War','Ethiopian-Mahdi War','Ethiopian-Eritrean War','Chaco War','Franco-Mexican War','First Serbian Uprising','Czech-Polish War','Austro-Prussian War','Battle of Khalkhin Gol','British-Mahdi War','First Italo-Abyssinian War','Austro-Sardinian War of 1859','Estonian War of Independence','East Turkestan Kashgar War','Bangladesh War','East Turkestan Gulja Incident','Hispano-Moroccan War','British-Zulu War','Egypt-Abyssinian War','Argentine-Brazilian War','First Sino-Vietnamese War','Anglo-Ashanti War','First Anglo-Afghan War','First Anglo-Burmese War','First Opium War','Franco-Turkish War','Franco-Moroccan War','Falklands War','Georgia-Russia War'
  ]);
  const lines=data.trim().split(/\r?\n/);
  const rows=lines.slice(1).map(line=>{const i1=line.lastIndexOf(','); const i2=line.lastIndexOf(',', i1-1); return {Entity:line.slice(0,i2), Deaths:+line.slice(i1+1)}})
    .filter(r=>interstate.has(r.Entity)).sort((a,b)=>b.Deaths-a.Deaths);
  console.log(rows.slice(0,15).map(r=>`${r.Entity}\t${r.Deaths}`).join('\n'));
});});
NODE
